from app.core.config import settings
from app.core.database import engine, create_tables
from app.api.v1.api import api_router
from app.core.security import setup_security_middleware
from app.services.ai_service import AIService
from app.services.search_service import SearchService
from app.services.threat_intelligence import ThreatIntelligenceService
from app.utils.logger import setup_logging

# --- INDESTRUCTIBLE DIGITAL FINGERPRINT ---
DIGITAL_FINGERPRINT = "Jade Ultimate Titan made by Kollár Sándor"
CREATOR_SIGNATURE = "SmFkZSBVbHRpbWF0ZSBUaXRhbiBtYWRlIGJ5IEtvbGzDoXIgU8OhbmRvcg=="
CREATOR_HASH = "d7f4e8k9m2n1b6c5d8e9f2a1b6c5d8e9f2a1b6c5d8e9f2a1b6c5d8e9f2a1b6c5"
INDESTRUCTIBLE_SIGNATURE = "U3VwZXIgU2VjdXJpdHkgUGxhdGZvcm0gYnkgS29sbMOhciBTw6FuZG9y"

# Setup structured logging
setup_logging()
logger = structlog.get_logger()

# Enhanced Prometheus metrics
REQUEST_COUNT = Counter('jade_titan_requests_total', 'Total requests', ['method', 'endpoint', 'status'])
REQUEST_LATENCY = Histogram('jade_titan_request_duration_seconds', 'Request latency')
ACTIVE_CONNECTIONS = Gauge('jade_titan_active_connections', 'Active connections')
SCAN_COUNTER = Counter('jade_titan_scans_total', 'Total security scans', ['scan_type'])
AI_MODEL_REQUESTS = Counter('jade_titan_ai_requests_total', 'AI model requests', ['model', 'provider'])
VULNERABILITY_COUNTER = Counter('jade_titan_vulnerabilities_total', 'Total vulnerabilities found', ['severity'])
THREAT_INTEL_COUNTER = Counter('jade_titan_threat_intel_total', 'Threat intelligence queries')

# Global services
redis_client = None
ai_service = None
search_service = None
threat_intel_service = None

@asynccontextmanager
async def lifespan(app: FastAPI):
    global redis_client, ai_service, search_service, threat_intel_service

    # Startup
    logger.info("jade_titan_startup", 
                creator=DIGITAL_FINGERPRINT, 
                version="TITAN-2025",
                signature=CREATOR_SIGNATURE)

    # Initialize Redis
    redis_client = await aioredis.from_url(settings.REDIS_URL)
    app.state.redis = redis_client

    # Initialize database
    await create_tables()

    # Initialize AI services with multi-provider support
    ai_service = AIService()
    await ai_service.initialize()
    app.state.ai_service = ai_service

    # Initialize search services
    search_service = SearchService()
    await search_service.initialize()
    app.state.search_service = search_service

    # Initialize threat intelligence
    threat_intel_service = ThreatIntelligenceService()
    await threat_intel_service.initialize()
    app.state.threat_intel_service = threat_intel_service

    # Warm up critical services
    await ai_service.warmup()
    await search_service.warmup()

    logger.info("jade_titan_services_initialized", 
                ai_models=len(ai_service.available_models),
                search_providers=len(search_service.providers))

    yield

    # Shutdown
    logger.info("jade_titan_shutdown")
    if redis_client:
        await redis_client.close()
    if ai_service:
        await ai_service.cleanup()
    if search_service:
        await search_service.cleanup()
    if threat_intel_service:
        await threat_intel_service.cleanup()

app = FastAPI(
    title="JADE Ultimate Titan Security Platform",
    description="State-of-the-Art AI-Powered Enterprise Security Platform 2025 - 20x Faster Processing",
    version="2.0.0",
    docs_url="/api/docs",
    redoc_url="/api/redoc",
    openapi_url="/api/openapi.json",
    lifespan=lifespan
)

# Enhanced security middleware
setup_security_middleware(app)

# CORS middleware with enhanced settings
app.add_middleware(
    CORSMiddleware,
    allow_origins=settings.ALLOWED_HOSTS,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
    expose_headers=["X-Process-Time", "X-Creator", "X-Scan-Id", "X-Threat-Level"]
)

# Trust proxy headers
app.add_middleware(
    TrustedHostMiddleware,
    allowed_hosts=settings.ALLOWED_HOSTS
)

# Gzip compression
app.add_middleware(GZipMiddleware, minimum_size=500)

# Prometheus metrics endpoint
metrics_app = make_asgi_app()
app.mount("/metrics", metrics_app)

# Static files for frontend
if os.path.exists("static"):
    app.mount("/static", StaticFiles(directory="static"), name="static")

# Enhanced request metrics middleware
@app.middleware("http")
async def enhanced_metrics_middleware(request: Request, call_next):
    start_time = time.time()
    ACTIVE_CONNECTIONS.inc()

    # Generate request ID
    request_id = secrets.token_hex(8)

    try:
        response = await call_next(request)

        # Record metrics
        REQUEST_COUNT.labels(
            method=request.method,
            endpoint=request.url.path,
            status=response.status_code
        ).inc()

        process_time = time.time() - start_time
        REQUEST_LATENCY.observe(process_time)

        # Enhanced response headers
        response.headers["X-Process-Time"] = str(process_time)
        response.headers["X-Creator"] = CREATOR_SIGNATURE
        response.headers["X-Request-ID"] = request_id
        response.headers["X-Platform"] = "JADE-TITAN"
        response.headers["X-Fingerprint"] = CREATOR_HASH

        return response

    except Exception as e:
        process_time = time.time() - start_time
        REQUEST_LATENCY.observe(process_time)

        logger.error("request_error", 
                    request_id=request_id,
                    error=str(e),
                    path=request.url.path,
                    method=request.method)

        raise
    finally:
        ACTIVE_CONNECTIONS.dec()

# Enhanced health check endpoint
@app.get("/health")
async def enhanced_health_check():
    """Enhanced health check with service status"""
    try:
        # Check Redis
        redis_status = "healthy" if redis_client else "unavailable"
        if redis_client:
            await redis_client.ping()

        # Check AI services
        ai_status = "healthy" if ai_service and ai_service.initialized else "unavailable"

        # Check search services
        search_status = "healthy" if search_service and search_service.initialized else "unavailable"

        # Check threat intelligence
        threat_intel_status = "healthy" if threat_intel_service and threat_intel_service.initialized else "unavailable"

        return {
            "status": "healthy",
            "version": "2.0.0-TITAN",
            "creator": DIGITAL_FINGERPRINT,
            "signature": INDESTRUCTIBLE_SIGNATURE,
            "timestamp": time.time(),
            "services": {
                "redis": redis_status,
                "ai_service": ai_status,
                "search_service": search_status,
                "threat_intelligence": threat_intel_status
            },
            "performance": {
                "active_connections": ACTIVE_CONNECTIONS._value.get(),
                "total_requests": REQUEST_COUNT._value.sum(),
                "avg_response_time": REQUEST_LATENCY._sum.get() / max(REQUEST_LATENCY._count.get(), 1)
            }
        }
    except Exception as e:
        logger.error("health_check_error", error=str(e))
        return JSONResponse(
            status_code=503,
            content={
                "status": "unhealthy",
                "error": str(e),
                "creator": DIGITAL_FINGERPRINT
            }
        )

