# JADE Ultimate Titan Security Platform - Enhanced Configuration
# Advanced configuration with multi-provider AI integration

import os
from typing import List, Optional, Dict, Any
from pydantic_settings import BaseSettings
from pydantic import Field, validator
import secrets

class Settings(BaseSettings):
    # Application settings
    APP_NAME: str = "JADE Ultimate Titan Security Platform"
    VERSION: str = "2.0.0-TITAN"
    DEBUG: bool = Field(default=False, env="DEBUG")

    # Security settings
    SECRET_KEY: str = Field(default_factory=lambda: secrets.token_urlsafe(32))
    ENCRYPTION_KEY: str = Field(default_factory=lambda: secrets.token_urlsafe(32))
    JWT_SECRET_KEY: str = Field(default_factory=lambda: secrets.token_urlsafe(32))
    JWT_ALGORITHM: str = "HS256"
    ACCESS_TOKEN_EXPIRE_MINUTES: int = 30
    REFRESH_TOKEN_EXPIRE_MINUTES: int = 60 * 24 * 7  # 7 days

    # Database settings
    DATABASE_URL: str = Field(
        default="postgresql+asyncpg://postgres:password@localhost:5432/jade_titan",
        env="DATABASE_URL"
    )
    DATABASE_POOL_SIZE: int = 30
    DATABASE_MAX_OVERFLOW: int = 50
