            model_name = self.preferred_models[0] if self.preferred_models else "llama-3.3-70b"
            model_config = AI_MODELS.get(model_name)

        provider = model_config["provider"]
        start_time = time.time()

        try:
            if provider == "cerebras":
                response = await self._call_cerebras_model(model_name, prompt, max_tokens)
            elif provider == "openai":
                response = await self._call_openai(model_config, prompt, max_tokens)
            elif provider == "google":
                response = await self._call_gemini(model_config, prompt, max_tokens)
            elif provider == "perplexity":
                response = await self._call_perplexity(model_config, prompt, max_tokens)
            elif provider == "jina":
                response = await self._call_jina(model_config, prompt, max_tokens)
            else:
                raise ValueError(f"Unsupported provider: {provider}")

            # Calculate performance metrics
            processing_time = time.time() - start_time
            speed_multiplier = model_config.get("speed_multiplier", 1)

            # Update performance metrics
            self.performance_metrics[model_name] = {
