    async def _call_cerebras_model(self, model_name: str, prompt: str, max_tokens: int) -> str:
        """Call Cerebras model (20x faster processing)"""
        try:
            model_config = AI_MODELS[model_name]

            # Use sync client in async context
            def _sync_call():
                return self.cerebras_client.chat.completions.create(
                    model=model_config["model"],
                    messages=[
                        {"role": "system", "content": "You are an expert cybersecurity analyst with advanced threat detection capabilities."},
                        {"role": "user", "content": prompt}
                    ],
                    max_tokens=max_tokens,
                    temperature=model_config.get("temperature", 0.1)
                )

            # Run in thread pool to avoid blocking
            loop = asyncio.get_event_loop()
            response = await loop.run_in_executor(None, _sync_call)

            return response.choices[0].message.content

        except Exception as e:
            logger.error("cerebras_call_error", model=model_name, error=str(e))
            raise

    async def _call_openai(self, model_config: Dict, prompt: str, max_tokens: int) -> str:
        """Call OpenAI API"""
        client = self.clients["openai"]

        response = await client.chat.completions.create(
            model=model_config["model"],
            messages=[
                {"role": "system", "content": "You are an expert cybersecurity analyst with advanced threat detection capabilities."},
                {"role": "user", "content": prompt}
            ],
            max_tokens=max_tokens,
            temperature=model_config.get("temperature", 0.1)
        )

        return response.choices[0].message.content

    async def _call_gemini(self, model_config: Dict, prompt: str, max_tokens: int) -> str:
        """Call Google Gemini API"""
        model = genai.GenerativeModel(model_config["model"])

        response = await model.generate_content_async(
            prompt,
            generation_config=genai.types.GenerationConfig(
                max_output_tokens=max_tokens,
                temperature=model_config.get("temperature", 0.1)
            )
        )

        return response.text

    async def _call_perplexity(self, model_config: Dict, prompt: str, max_tokens: int) -> str:
        """Call Perplexity AI API"""
        perplexity_config = self.clients["perplexity"]

        async with aiohttp.ClientSession() as session:
            headers = {
                "Authorization": f"Bearer {perplexity_config['api_key']}",
                "Content-Type": "application/json"
            }

            payload = {
                "model": "sonar-pro",
                "messages": [
                    {"role": "system", "content": "You are an expert cybersecurity analyst with advanced threat detection capabilities."},
                    {"role": "user", "content": prompt}
                ],
                "max_tokens": max_tokens,
                "temperature": model_config.get("temperature", 0.1)
            }

            async with session.post(
                f"{perplexity_config['base_url']}/chat/completions",
                headers=headers,
                json=payload
            ) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    return data["choices"][0]["message"]["content"]
                else:
                    raise Exception(f"Perplexity API error: {resp.status}")

    async def _call_jina(self, model_config: Dict, prompt: str, max_tokens: int) -> str:
        """Call Jina AI API"""
        jina_config = self.clients["jina"]

        async with aiohttp.ClientSession() as session:
            headers = {
                "Authorization": f"Bearer {jina_config['api_key']}",
                "Content-Type": "application/json"
            }

            payload = {
                "model": "jina-chat",
                "messages": [
                    {"role": "system", "content": "You are an expert cybersecurity analyst with advanced threat detection capabilities."},
                    {"role": "user", "content": prompt}
