            )[:max_results]

            # Remove duplicates based on URL
            seen_urls = set()
            unique_results = []
            for result in aggregated_results["results"]:
                url = result.get("url", "")
                if url not in seen_urls:
                    seen_urls.add(url)
                    unique_results.append(result)

            aggregated_results["results"] = unique_results
            aggregated_results["metadata"]["search_time"] = time.time() - start_time
            aggregated_results["metadata"]["total_results"] = len(unique_results)

            logger.info("multi_provider_search_completed",
