            async with aiohttp.ClientSession() as session:
                headers = {
                    "Authorization": f"Bearer {provider_config['api_key']}",
                    "Accept": "application/json"
                }

                # Use Jina's search endpoint
                search_url = f"{provider_config['base_url']}/{query}"

                async with session.get(
                    search_url,
                    headers=headers
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        return self._format_jina_results(data, query)
                    else:
                        error_text = await response.text()
                        raise Exception(f"Jina API error {response.status}: {error_text}")

        except Exception as e:
            logger.error("jina_search_error", error=str(e))
            raise

    def _format_exa_results(self, data: Dict) -> Dict[str, Any]:
        """Format EXA search results"""
        results = []

        for item in data.get("results", []):
            results.append({
                "title": item.get("title", ""),
                "url": item.get("url", ""),
                "snippet": item.get("text", ""),
                "score": item.get("score", 0),
                "published_date": item.get("published_date", ""),
                "author": item.get("author", ""),
                "domain": item.get("url", "").split("/")[2] if "/" in item.get("url", "") else ""
            })

        return {
            "provider": "exa",
            "query": data.get("query", ""),
            "results": results,
            "total_results": len(results),
            "search_type": "neural"
        }

    def _format_brave_results(self, data: Dict) -> Dict[str, Any]:
        """Format Brave search results"""
        results = []

        web_results = data.get("web", {}).get("results", [])
        for item in web_results:
            results.append({
                "title": item.get("title", ""),
                "url": item.get("url", ""),
                "snippet": item.get("description", ""),
                "score": 1.0,  # Brave doesn't provide scores
                "published_date": item.get("age", ""),
                "domain": item.get("url", "").split("/")[2] if "/" in item.get("url", "") else ""
            })

        return {
            "provider": "brave",
            "query": data.get("query", {}).get("original", ""),
            "results": results,
            "total_results": len(results),
            "search_type": "web"
        }

    def _format_tavily_results(self, data: Dict) -> Dict[str, Any]:
        """Format Tavily search results"""
        results = []

        for item in data.get("results", []):
            results.append({
                "title": item.get("title", ""),
                "url": item.get("url", ""),
                "snippet": item.get("content", ""),
                "score": item.get("score", 0),
                "published_date": item.get("published_date", ""),
                "domain": item.get("url", "").split("/")[2] if "/" in item.get("url", "") else ""
            })

        return {
            "provider": "tavily",
            "query": data.get("query", ""),
            "results": results,
            "total_results": len(results),
            "search_type": "research",
            "answer": data.get("answer", "")
        }

    def _format_perplexity_results(self, data: Dict, query: str) -> Dict[str, Any]:
        """Format Perplexity search results"""
        results = []

        # Extract citations if available
        citations = data.get("citations", [])
        for i, citation in enumerate(citations):
            results.append({
                "title": f"Perplexity Result {i+1}",
                "url": citation.get("url", ""),
                "snippet": citation.get("text", ""),
                "score": 1.0,
                "published_date": "",
                "domain": citation.get("url", "").split("/")[2] if "/" in citation.get("url", "") else ""
            })

        # If no citations, create result from content
        if not results:
            content = data.get("choices", [{}])[0].get("message", {}).get("content", "")
            if content:
                results.append({
                    "title": "Perplexity AI Response",
                    "url": "",
                    "snippet": content[:300] + "..." if len(content) > 300 else content,
                    "score": 1.0,
                    "published_date": "",
                    "domain": "perplexity.ai"
                })

        return {
            "provider": "perplexity",
            "query": query,
            "results": results,
            "total_results": len(results),
            "search_type": "ai_powered",
            "answer": data.get("choices", [{}])[0].get("message", {}).get("content", "")
        }

    def _format_jina_results(self, data: Dict, query: str) -> Dict[str, Any]:
        """Format Jina search results"""
        results = []

        # Handle Jina's response format
        if isinstance(data, dict) and "data" in data:
            for item in data["data"]:
                results.append({
                    "title": item.get("title", ""),
                    "url": item.get("url", ""),
                    "snippet": item.get("description", ""),
                    "score": item.get("score", 0),
                    "published_date": item.get("date", ""),
                    "domain": item.get("url", "").split("/")[2] if "/" in item.get("url", "") else ""
                })

        return {
            "provider": "jina",
            "query": query,
            "results": results,
            "total_results": len(results),
            "search_type": "content"
        }

    async def get_search_analytics(self) -> Dict[str, Any]:
        """Get search service analytics"""
        return {
            "providers_available": list(self.providers.keys()),
            "total_providers": len(self.providers),
            "performance_metrics": self.performance_metrics,
            "cache_size": len(self.search_cache),
            "service_status": "healthy" if self.initialized else "initializing"
        }

    async def cleanup(self):
        """Clean up search service resources"""
        try:
            # Clear cache
            self.search_cache = {}

            # Reset providers
            self.providers = {}
            self.initialized = False

            logger.info("search_service_cleanup_completed")
        except Exception as e:
            logger.error("search_service_cleanup_error", error=str(e))
